package com.dy.artisan3d.data.mapperimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleDtoimport com.dy.artisan3d.data.model.artisan.article.ArtisanArticleTranslationDtoimport com.dy.artisan3d.domain.model.artisan.ArtisanArticlefun ArtisanArticleDto.toDomain(targetLang: String,clearHtml: Boolean = true): ArtisanArticle {    val translation = translations[targetLang]        ?: translations.values.firstOrNull()        ?: ArtisanArticleTranslationDto()    val fullHtml = translation.text ?: ""    val plainText = fullHtml        .replace("<p>", "")           // <p> ni olib tashlash        .replace("</p>", "\n\n")      // </p> ni ikki yangi qatorga almashtirish        .replace(Regex("<[^>]*>"), "") // Qolgan barcha HTML teglarni olib tashlash        .replace("&nbsp;", " ")        // &nbsp; ni bo'sh joyga almashtirish        .replace(Regex("\n{3,}"), "\n\n") // 3 va undan ko'p \n ni 2 ta \n ga qisqartirish        .trim()    val shortDescription = if (plainText.length > 120) {        plainText.take(120).trim() + "..."    } else {        plainText    }    return ArtisanArticle(        id = id,        slug = slug,        author = translation.author ?: "Unknown",        title = translation.title ?: "No Title",        shortDesc = shortDescription,        contentHtml = plainText  // Endi bu to'liq formatlangan oddiy matn    )}